import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.CWdVbaJB.js";const m=JSON.parse('{"title":"ATT&CK Mapping","description":"","frontmatter":{"title":"ATT&CK Mapping"},"headers":[],"relativePath":"security/attack-mapping.md","filePath":"security/attack-mapping.md"}'),n={name:"security/attack-mapping.md"};function o(s,e,d,c,p,l){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="att-ck-mapping" tabindex="-1">ATT&amp;CK Mapping <a class="header-anchor" href="#att-ck-mapping" aria-label="Permalink to &quot;ATT&amp;CK Mapping&quot;">​</a></h1><p>SHAVIRA maps detection rules and findings to the <a href="https://attack.mitre.org/" target="_blank" rel="noreferrer">MITRE ATT&amp;CK</a> framework, providing a common language for describing AI security threats.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>When creating or editing a detection rule, you can specify one or more ATT&amp;CK technique IDs in the <strong>ATT&amp;CK IDs</strong> field. These IDs link your detections to specific attack techniques in the MITRE framework.</p><h2 id="detection-artifacts" tabindex="-1">Detection Artifacts <a class="header-anchor" href="#detection-artifacts" aria-label="Permalink to &quot;Detection Artifacts&quot;">​</a></h2><p>Each finding can include detection artifacts that provide actionable intelligence:</p><h3 id="sigma-rules" tabindex="-1">Sigma Rules <a class="header-anchor" href="#sigma-rules" aria-label="Permalink to &quot;Sigma Rules&quot;">​</a></h3><p>The Sigma YAML from the detection rule that generated the finding. Can be exported and imported into other Sigma-compatible tools.</p><h3 id="siem-queries" tabindex="-1">SIEM Queries <a class="header-anchor" href="#siem-queries" aria-label="Permalink to &quot;SIEM Queries&quot;">​</a></h3><p>Pre-built queries for common SIEM platforms, generated from the Sigma rule logic.</p><h3 id="att-ck-technique-references" tabindex="-1">ATT&amp;CK Technique References <a class="header-anchor" href="#att-ck-technique-references" aria-label="Permalink to &quot;ATT&amp;CK Technique References&quot;">​</a></h3><p>Links to the MITRE ATT&amp;CK knowledge base for each mapped technique, providing:</p><ul><li>Technique description and procedure examples</li><li>Mitigation recommendations</li><li>Detection guidance from the ATT&amp;CK framework</li></ul><h2 id="common-ai-ml-att-ck-techniques" tabindex="-1">Common AI/ML ATT&amp;CK Techniques <a class="header-anchor" href="#common-ai-ml-att-ck-techniques" aria-label="Permalink to &quot;Common AI/ML ATT&amp;CK Techniques&quot;">​</a></h2><p>Relevant techniques for AI workload security:</p><table tabindex="0"><thead><tr><th>ID</th><th>Technique</th><th>AI Relevance</th></tr></thead><tbody><tr><td>T1059</td><td>Command and Scripting Interpreter</td><td>Agent tool-use executing arbitrary code</td></tr><tr><td>T1190</td><td>Exploit Public-Facing Application</td><td>Prompt injection via public AI endpoints</td></tr><tr><td>T1530</td><td>Data from Cloud Storage Object</td><td>Model accessing unauthorized data sources</td></tr><tr><td>T1552</td><td>Unsecured Credentials</td><td>API keys or tokens exposed in prompts/outputs</td></tr><tr><td>T1071</td><td>Application Layer Protocol</td><td>Exfiltration through model responses</td></tr><tr><td>T1027</td><td>Obfuscated Files or Information</td><td>Encoded payloads in prompts</td></tr></tbody></table><h2 id="adding-att-ck-ids-to-rules" tabindex="-1">Adding ATT&amp;CK IDs to Rules <a class="header-anchor" href="#adding-att-ck-ids-to-rules" aria-label="Permalink to &quot;Adding ATT&amp;CK IDs to Rules&quot;">​</a></h2><p>In the rule editor, enter technique IDs as a comma-separated list:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>T1059, T1190, T1552</span></span></code></pre></div><p>These IDs are stored on the detection rule and propagated to any findings generated by that rule.</p><h2 id="exporting-mappings" tabindex="-1">Exporting Mappings <a class="header-anchor" href="#exporting-mappings" aria-label="Permalink to &quot;Exporting Mappings&quot;">​</a></h2><p>When exporting a detection rule, ATT&amp;CK IDs are included in all export formats (Sigma, JSON, YAML). This enables integration with other security tools that consume ATT&amp;CK-mapped detection content.</p>',22)])])}const u=t(n,[["render",o]]);export{m as __pageData,u as default};
